-- Patient Safety & Quality Improvement: Part 6 (Questions 251-300)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- TEAMWORK & COMMUNICATION (TEAMSTEPPS)
    (v_topic_id, 'Which of the following is a core competency of the TeamSTEPPS framework?', '["Team Leadership", "Situational Monitoring", "Mutual Support", "All of the above"]', 3, 'TeamSTEPPS is a comprehensive system to improve communication and teamwork skills among healthcare professionals.'),
    (v_topic_id, 'A "Briefing" is a team event used to:', '["Review performance after a shift", "Plan and share the mental model before a task or procedure", "Discuss the hospital budget", "Interview new employees"]', 1, 'Briefings occur BEFORE a task to ensure everyone is on the same page regarding the plan and potential risks.'),
    (v_topic_id, 'A "Debriefing" is a team event used to:', '["Plan for the next day", "Reflect on a previous event to identify what went well and what could be improved", "Assign daily tasks", "Order medical supplies"]', 1, 'Debriefings occur AFTER an event and are critical for continuous learning and system improvement.'),
    (v_topic_id, 'Which tool is used for "Graded Assertiveness" when a team member has a safety concern?', '["SBAR", "CUS (Concerned, Uncomfortable, Safety issue)", "I-PASS", "Check-back"]', 1, 'CUS provides a structured way to escalate a concern, from expressing concern to stating it is a safety issue.'),
    (v_topic_id, 'The "Call-Out" technique is used during an emergency to:', '["Call for help", "Communicate critical information to the whole team simultaneously (e.g., \"Airway is clear!\")", "Ask for a coffee", "Tell a joke to relieve stress"]', 1, 'Call-outs ensure everyone has the same real-time information during a fast-paced event.'),

    -- SITUATIONAL AWARENESS & SUPPORT
    (v_topic_id, 'In a medical team, a "Shared Mental Model" means:', '["Everyone thinks exactly the same way", "The team has a common understanding of the plan, the patient''s status, and the goals", "Everyone has the same medical degree", "The team uses the same computer"]', 1, 'A shared mental model allows for better coordination and anticipation of each other''s needs.'),
    (v_topic_id, '"Situational Monitoring" is the process of:', '["Watching the clock", "Actively scanning and assessing the situation to maintain situational awareness", "Monitoring the hospital''s social media", "Checking the weather"]', 1, 'It involves "knowing what is going on around you" to detect early signs of trouble.'),
    (v_topic_id, '"Mutual Support" in a team includes which of the following?', '["Back-up behavior (helping a busy colleague)", "Constructive feedback", "Advocacy for the patient", "All of the above"]', 3, 'Support ensures that no individual member is overwhelmed and that the patient remains safe.'),
    (v_topic_id, 'The "Two-Challenge Rule" requires a team member to voice their concern at least twice if:', '["They are bored", "They believe a safety rule is being violated or the patient is at risk", "They want a raise", "They disagree with the lunch choice"]', 1, 'If the initial concern is ignored, a second "challenge" is required to ensure the message is received.'),
    (v_topic_id, 'When a team member "Stops the Line," they are:', '["Stopping the surgical incision", "Halting a process or procedure because of a perceived immediate safety threat", "Quitting their job", "Hanging up the phone"]', 1, 'Stopping the line is an essential safety behavior in high-reliability organizations.'),

    -- HUMAN FACTORS & COGNITIVE LOAD
    (v_topic_id, 'Why is "Fatigue" a major latent error in healthcare?', '["It makes people more creative", "It impairs cognitive function, reaction time, and judgment similarly to alcohol intoxication", "It reduces the cost of labor", "It is only a problem for junior staff"]', 1, 'Sleep deprivation is a biological limit; safe systems must manage work hours and provide for adequate rest.'),
    (v_topic_id, '"Cognitive Load" refers to:', '["The weight of a medical textbook", "The total amount of mental effort being used in the working memory", "The number of patients on a floor", "The speed of the internet"]', 1, 'When cognitive load is too high (e.g., due to noise, distractions, or complex tasks), the risk of error increases significantly.'),
    (v_topic_id, 'Which of the following is a "Human Factors" strategy to reduce cognitive load?', '["Using checklists and standardized order sets", "Increasing the number of alarms", "Working in a noisy environment", "Multitasking as much as possible"]', 0, 'Off-loading memory to external tools (checklists, automation) frees up mental capacity for complex clinical judgment.'),
    (v_topic_id, 'Which of the following is an example of "User-Centered Design" in healthcare?', '["Designing an EHR based on what software engineers think is easy", "Involving clinicians in the design and testing of a new medical device to ensure it is intuitive", "Buying the cheapest equipment available", "Changing the layout of the hospital every week"]', 1, 'User-centered design ensures that tools work for the people who actually use them in high-stress environments.'),
    (v_topic_id, '"Usability Testing" identifies:', '["How much an item costs", "Whether a user can use a product to achieve a specific goal effectively and safely", "The physical weight of a device", "How many people will buy the product"]', 1, 'Usability testing is a critical safety step before deploying new technology or equipment.'),

    -- ALARM FATIGUE & TECHNOLOGY
    (v_topic_id, '"Alarm Fatigue" occurs when:', '["A monitor breaks", "Clinicians become desensitized to safety alerts due to a high volume of false or non-actionable alarms", "A patient sleeps through an alarm", "The alarm volume is too low"]', 1, 'It is a major safety hazard leading to missed critical events.'),
    (v_topic_id, 'Which of the following is a "System Level" solution to alarm fatigue?', '["Firing staff who miss alarms", "Customizing alarm parameters for individual patients and eliminating non-critical alerts", "Turning off all monitors", "Increasing the volume of all alarms"]', 1, 'Refining the "signal-to-noise" ratio is the key to safe monitoring.'),
    (v_topic_id, 'In EHR design, a "Passive Alert" is one that:', '["Stops the user from proceeding", "Appears as a small icon or text on the screen without interrupting the workflow", "Makes a loud sound", "Is only visible to the administrator"]', 1, 'Passive alerts are less likely to cause fatigue but are also more easily missed.'),
    (v_topic_id, 'An "Interruptive Alert" (Pop-up) in an EHR should be reserved for:', '["Routine information", "High-risk safety warnings (e.g., severe drug-allergy interaction)", "Hospital announcements", "Billing reminders"]', 1, 'Interruptive alerts are high-leverage and should be used sparingly to maintain their effectiveness.'),
    (v_topic_id, 'What is the "Automation Bias"?', '["The tendency to favor machines over humans", "The tendency to over-rely on automated systems and ignore contradictory information", "A preference for manual tasks", "The fear of robots"]', 1, 'If a "smart pump" or EHR says something is safe, a clinician might ignore their own judgment that it is not.'),

    -- PHYSICAL ENVIRONMENT & FALLS
    (v_topic_id, 'Which of the following is the most common adverse event in the geriatric inpatient population?', '["Surgical site infection", "Falls", "Medication errors", "Diagnostic delay"]', 1, 'Falls are a major source of hospital-acquired injury in older adults.'),
    (v_topic_id, 'Which of the following is a "Structural" intervention to prevent falls?', '["A lecture on fall prevention", "Nonslip flooring and grab bars in bathrooms", "Telling the patient to stay in bed", "Checking the patient''s heart rate"]', 1, 'Structural modifications (the physical environment) are more reliable than "reminders."'),
    (v_topic_id, 'The "Morse Fall Scale" is a tool used to:', '["Measure the distance of a fall", "Assess a patient''s risk for falling based on history and clinical factors", "Calculate the cost of a fall", "Predict the weather"]', 1, 'Risk assessment allows for the implementation of targeted fall-prevention bundles for high-risk patients.'),
    (v_topic_id, 'What is the "Safe Room" concept in behavioral health?', '["A room with a TV", "An environment designed to minimize the risk of self-harm or suicide (e.g., no ligatures, weighted furniture)", "A room that is always locked", "A room in the basement"]', 1, 'Environmental design is the primary safety layer for patients at risk of suicide.'),
    (v_topic_id, 'Why is "Noise" in the hospital a safety issue?', '["It makes the hospital look busy", "It contributes to patient sleep deprivation and clinician fatigue/distraction", "It is only a problem for the staff", "It increases hospital revenue"]', 1, 'Noise pollution is a latent environmental stressor that impacts both patient healing and staff performance.'),

    -- HUMAN FACTORS IN DOCUMENTATION
    (v_topic_id, 'Which of the following is a "Documentation" error that impacts safety?', '["Using unapproved abbreviations (e.g., \"u\" for units)", "Copying and pasting old notes without updating the information (\"Note Bloat\")", "Entering data for the wrong patient", "All of the above"]', 3, 'Errors in the record can lead to major treatment mistakes by other team members.'),
    (v_topic_id, 'The Joint Commission''s "Do Not Use" list includes which of the following?', '["u (units)", "IU (International Units)", "q.d. (daily)", "All of the above"]', 3, 'These abbreviations are easily misread (e.g., "u" can be read as "0"), leading to 10-fold dosing errors.'),
    (v_topic_id, 'What is the primary safety risk of "Copy-Forward" (Clone) documentation?', '["It saves too much time", "It can perpetuate outdated or incorrect information throughout the medical record", "It makes the note too long", "It is illegal"]', 1, 'Note bloat and the "copying" of errors are major hazards of electronic documentation.'),
    (v_topic_id, '"Computerized Physician Order Entry" (CPOE) eliminates which type of error?', '["Diagnostic error", "Illegible handwriting errors", "Wrong patient identification", "Allergic reactions"]', 1, 'CPOE solves the legibility problem, though it introduces new risks like "drop-down menu" errors.'),
    (v_topic_id, 'A "Forcing Function" in an EHR is best exemplified by:', '["A reminder to wash hands", "A field that must be completed before the order can be signed", "A list of past medications", "A link to a research paper"]', 1, 'Mandatory fields force the user to provide critical safety information.'),

    -- COMMUNICATION TOOLS REVISITED
    (v_topic_id, 'The "S" in SBAR stands for "Situation." Which of the following is a correct "S" statement?', '["The patient has a history of COPD and heart failure", "I am calling because Mr. Jones in Room 10 has a new onset of severe chest pain", "I think the patient is having an MI", "I recommend giving 324mg of Aspirin"]', 1, 'The situation is the immediate reason for the call.'),
    (v_topic_id, 'The "A" in SBAR is the "Assessment." This represents:', '["A list of all the patient''s lab results", "The clinician''s interpretation of what is happening", "A physical exam of the patient''s abdomen", "The patient''s age and gender"]', 1, 'Assessment is the "So what?" or the clinician''s conclusion based on the facts.'),
    (v_topic_id, 'A "Read-Back" is required for which of the following?', '["Verbal orders", "Telephone orders", "Critical lab results", "All of the above"]', 3, 'Verifying the accuracy of verbal information is a fundamental safety requirement.'),
    (v_topic_id, 'In the "I-PASS" handoff, the "Action List" includes:', '["The patient''s family history", "A \"To-Do\" list of tasks that need to be completed by the next shift", "A list of things that went wrong", "The names of all the nurses"]', 1, 'A clear action list ensures that essential tasks are not forgotten during the shift.'),
    (v_topic_id, 'The "Synthesis" step at the end of a handoff requires the RECEIVER to:', '["Sign the paper", "Briefly summarize the plan and ask questions to confirm understanding", "Leave the room", "Take a break"]', 1, 'This is the "closed-loop" part of the handoff.'),

    -- MISC HUMAN FACTORS
    (v_topic_id, 'What is "Hick''s Law" in design?', '["The more choices a person has, the longer it takes to make a decision", "Safety is directly proportional to cost", "The hospital should have at least 10 exits", "Errors are unavoidable"]', 0, 'In a crisis, a system with too many options (e.g., a complex monitor screen) can slow down critical action.'),
    (v_topic_id, 'The "Cockpit Resource Management" (CRM) principles from aviation were adapted for medicine as:', '["TeamSTEPPS", "RCA", "PDSA", "FMEA"]', 0, 'CRM focuses on non-technical skills like communication, leadership, and decision-making.'),
    (v_topic_id, 'A "Checklist" is a cognitive aid designed to support __________.', '["Long-term memory", "Working memory and attention", "The hospital budget", "Patient entertainment"]', 1, 'Checklists prevent "slips" or "lapses" when the brain is under stress.'),
    (v_topic_id, 'What is "Distraction" in the medication room?', '["A source of entertainment", "A latent error that increases the risk of active failure", "A way to make the work day faster", "A sign of a good team"]', 1, 'Distractions are "safety killers" in high-concentration tasks.'),
    (v_topic_id, 'A "Sterile Cockpit Rule" in nursing refers to:', '["Mopping the floor before every shift", "Eliminating all non-essential conversation and distraction during critical tasks like medication preparation", "Using only sterile equipment", "Not allowing patients to talk"]', 1, 'Adapted from aviation, this rule protects the focus of the clinician during high-risk activities.'),

    -- FINAL HUMAN FACTORS
    (v_topic_id, 'The "Swiss Cheese" model was designed to explain:', '["Why cheese has holes", "How multiple system failures align to cause an accident", "The nutritional value of hospital food", "How to cut costs in the kitchen"]', 1, 'It is the most widely accepted model of organizational accident causation.'),
    (v_topic_id, 'In a "Just Culture," if a person makes a mistake because the system is poorly designed, the primary response should be:', '["Firing the person", "Redesigning the system", "Suspending the person", "Fining the person"]', 1, 'Safe systems don''t blame individuals for system failures.'),
    (v_topic_id, 'What is the "Halo Effect" in a team?', '["A religious experience", "The tendency to assume someone is competent in one area because they are competent in another", "A type of lighting in the OR", "The feeling of being safe"]', 1, 'The halo effect can lead team members to not question the actions of a "famous" or "senior" surgeon, even when they see an error.'),
    (v_topic_id, 'The "Sunk Cost Fallacy" in surgery might lead a surgeon to:', '["Stop a surgery early", "Continue a failing operation because they have already spent 6 hours on it", "Charge the patient more", "Ask for a second opinion"]', 1, 'Bias can cloud the judgment of when to change the plan for the patient''s safety.'),
    (v_topic_id, 'What is the most effective way to improve communication in a clinical unit?', '["Sending more emails", "Implementing structured tools (SBAR, I-PASS) and regular team training", "Hiring a new manager", "Buying faster computers"]', 1, 'Structure and training are the keys to reliable communication.'),

    -- ADDITIONAL HUMAN FACTORS
    (v_topic_id, 'In the context of information overload, what is the "Signal-to-Noise Ratio"?', '["The volume of the hospital intercom", "The ratio of relevant, actionable information to irrelevant or distracting data", "The number of patients per nurse", "The speed of the pharmacy tube system"]', 1, 'In high-stakes environments, increasing the signal (relevant data) while reducing noise (distractions, false alarms) is a critical safety strategy.'),
    (v_topic_id, 'Which of the following is a "Physical Environment" stressor that can increase medical errors?', '["Dim lighting in medication preparation areas", "Excessive ambient noise in the ICU", "Poorly designed storage layouts for similar-looking vials", "All of the above"]', 3, 'Latent environmental factors can significantly impact the performance of front-line staff.'),
    (v_topic_id, '"Selective Perception" can lead a clinician to:', '["Ignore clinical data that contradicts their initial diagnosis", "Only see the patients they like", "Hear only the loudest alarms", "Forget to wash their hands"]', 0, 'Selective perception is a cognitive bias where we "see what we expect to see" or what aligns with our current hypothesis.'),
    (v_topic_id, 'What is the purpose of "Peer Review" in patient safety?', '["To punish doctors who make mistakes", "For colleagues to evaluate each other''s work to identify areas for quality improvement and learning", "To decide on hospital promotions", "To audit the hospital''s financial records"]', 1, 'Peer review is a professional mechanism for continuous learning and maintaining standards of care.'),
    (v_topic_id, 'A "Culture of Inquiry" in a medical team encourages members to:', '["Ask \"Why?\" and \"What if?\" to better understand risks and systems", "Question the patient''s insurance", "Audit each other''s salaries", "Focus only on their own tasks"]', 0, 'An inquisitive culture is a hallmark of high-reliability organizations that are preoccupied with potential failures.')
END $$;
